library(shiny)
library(bslib)
library(ggplot2)

# Define the asset themes (Icons map to FontAwesome 6, sounds point to free Google audio CDNs)
themes_data <- list(
  "Thunderstorm" = list(icon = "bolt", sound = "https://actions.google.com/sounds/v1/weather/thunder_crack.ogg", color = "#F6E05E"),
  "Cowbell"      = list(icon = "music", sound = "https://actions.google.com/sounds/v1/cartoon/cartoon_cowbell.ogg", color = "#C0C0C0"),
  "Dinner Bell"  = list(icon = "bell", sound = "https://actions.google.com/sounds/v1/alarms/dinner_bell_triangle.ogg", color = "#F6AD55"),
  "Clown"        = list(icon = "face-grin-tongue-squint", sound = "https://actions.google.com/sounds/v1/cartoon/clown_horn.ogg", color = "#F687B3"),
  "Woodblock"    = list(icon = "tree", sound = "https://actions.google.com/sounds/v1/cartoon/hitting_a_woodblock.ogg", color = "#B7791F"),
  "Tree Chop"    = list(icon = "tree", sound = "https://actions.google.com/sounds/v1/impacts/chopping_hollow_tree.ogg", color = "#2A7E19"),
  "Glass"        = list(icon = "wine-glass", sound = "https://actions.google.com/sounds/v1/impacts/wine_glass_shatter.ogg", color = "#722F37")
)

ui <- page_sidebar(
  title = "Poisson Process Simulator",
  theme = bs_theme(version = 5, bootswatch = "flatly"),
  
  # Inject Custom CSS and JavaScript for the black screen timer and animations
  tags$head(
    tags$style(HTML("
      #sim-screen {
        position: fixed; top: 0; left: 0; width: 100vw; height: 100vh;
        background-color: black; z-index: 9999; display: none;
        color: white; font-family: 'Courier New', Courier, monospace;
        flex-direction: column; align-items: center; justify-content: space-between;
        padding: 5vh 0;
      }
      .sim-text { font-size: 6vh; font-weight: bold; }
      #sim-icon { 
        font-size: 40vh; opacity: 0; 
        transition: opacity 0.1s ease-out; 
        display: flex; align-items: center; justify-content: center;
        flex-grow: 1;
      }
    ")),
    tags$script(HTML("
      // Trick to unlock browser audio policy immediately on button click
      $(document).on('click', '#startSim', function() {
          let silentAudio = new Audio('data:audio/wav;base64,UklGRigAAABXQVZFZm10IBIAAAABAAEARKwAAIhYAQACABAAAABkYXRhAgAAAAEA');
          silentAudio.play().catch(e => {});
      });

      Shiny.addCustomMessageHandler('runSimulation', function(msg) {
          let timestamps = msg.timestamps;
          let duration = msg.duration;
          let iconClass = msg.icon;
          let soundUrl = msg.sound;
          let color = msg.color;
          
          let baseAudio = new Audio(soundUrl);
          baseAudio.load();

          let simScreen = document.getElementById('sim-screen');
          let iconEl = document.getElementById('sim-icon-inner');
          let timerEl = document.getElementById('sim-timer');
          let counterEl = document.getElementById('sim-counter');
          let iconContainer = document.getElementById('sim-icon');

          iconEl.className = 'fa-solid fa-' + iconClass;
          iconEl.style.color = color;
          simScreen.style.display = 'flex';

          let startTime = performance.now();
          let eventIndex = 0;
          let count = 0;

          function loop(currentTime) {
              let elapsed = (currentTime - startTime) / 1000;
              
              timerEl.innerText = elapsed.toFixed(2) + 's';
              counterEl.innerText = 'Observations: ' + count;

              // Check if we have passed the next event timestamp
              while(eventIndex < timestamps.length && timestamps[eventIndex] <= elapsed) {
                  count++;
                  eventIndex++;
                  
                  // Trigger Audio (allows overlapping sounds)
                  let audio = baseAudio.cloneNode();
                  audio.play().catch(e => console.log('Audio blocked:', e));
                  
                  // Force the audio to stop after 500ms
                  setTimeout(() => { 
                      audio.pause(); 
                  }, 500);

                  // Trigger Icon Flash
                  iconContainer.style.opacity = 1;
                  setTimeout(() => { iconContainer.style.opacity = 0; }, 500);
              }

              if(elapsed < duration) {
                  requestAnimationFrame(loop);
              } else {
                  // End simulation, hide screen, alert Shiny
                  simScreen.style.display = 'none';
                  Shiny.setInputValue('simFinished', {count: count, t: Date.now()});
              }
          }
          requestAnimationFrame(loop);
      });
    "))
  ),
  
  # Hidden div to ensure FontAwesome dependencies are loaded by Shiny
  tags$div(style = "display: none;", 
           icon("bolt"), icon("droplet"), icon("bell"), 
           icon("hands-clapping"), icon("music"), icon("drum")),
  
  # The Full-Screen Simulation Overlay
  tags$div(id = "sim-screen",
           tags$div(id = "sim-counter", class = "sim-text", "Observations: 0"),
           tags$div(id = "sim-icon", tags$i(id = "sim-icon-inner", class = "")),
           tags$div(id = "sim-timer", class = "sim-text", "0.00s")
  ),
  
  sidebar = sidebar(
    title = "Simulation Parameters",
    numericInput("rate", "Rate Parameter (λ):", value = 2, min = 0.01, step = 0.5),
    selectInput("timeUnit", "Per Unit of Time:", 
                choices = c("Second" = 1, "Minute" = 60, "Hour" = 3600)),
    numericInput("duration", "Run Experiment For (seconds):", value = 15, min = 1, max = 300),
    selectInput("theme", "Audio/Icon Theme:", choices = names(themes_data)),
    hr(),
    actionButton("startSim", "Start Simulation", class = "btn-lg btn-success", width = "100%")
  ),
  
  # Main Panel UI
  uiOutput("resultsUI")
)

server <- function(input, output, session) {
  
  # Store the event timestamps to build the plot after the simulation ends
  sim_times <- reactiveVal(NULL)
  
  # Initial Welcome Screen vs Results Screen
  output$resultsUI <- renderUI({
    if (is.null(sim_times())) {
      card(
        card_header("Welcome"),
        p("Set your rate parameter (λ), choose a theme, and hit Start. The screen will black out, and the counting process will begin.")
      )
    } else {
      layout_columns(
        col_widths = 12,
        uiOutput("summaryStats"),
        card(
          card_header("Counting Process N(t) Step Function"),
          plotOutput("stepPlot", height = "400px")
        )
      )
    }
  })
  
  observeEvent(input$startSim, {
    # 1. Calculate rate strictly in "per second" for the backend engine
    rate_per_sec <- input$rate / as.numeric(input$timeUnit)
    total_time <- input$duration
    
    # 2. Pre-generate exponential inter-arrival times
    times <- numeric(0)
    current_time <- 0
    
    # Generate jumps until we exceed the total duration
    while(TRUE) {
      step <- rexp(1, rate = rate_per_sec)
      current_time <- current_time + step
      if(current_time > total_time) break
      times <- c(times, current_time)
    }
    
    sim_times(times)
    
    # 3. Fetch selected theme details
    selected_theme <- themes_data[[input$theme]]
    
    # 4. Dispatch exactly what will happen to the JavaScript engine
    session$sendCustomMessage("runSimulation", list(
      timestamps = times,
      duration = total_time,
      icon = selected_theme$icon,
      sound = selected_theme$sound,
      color = selected_theme$color
    ))
  })
  
  # Triggers when JavaScript finishes the countdown and closes the black screen
  observeEvent(input$simFinished, {
    
    output$summaryStats <- renderUI({
      times <- sim_times()
      actual_n <- length(times)
      rate_per_sec <- input$rate / as.numeric(input$timeUnit)
      expected_n <- rate_per_sec * input$duration
      
      inter_arrivals <- if (actual_n > 0) diff(c(0, times)) else NA
      mean_ia <- if (!is.na(inter_arrivals[1])) round(mean(inter_arrivals), 3) else NA
      
      layout_columns(
        value_box("Realized Events", actual_n, theme = "primary", showcase = icon("hashtag")),
        value_box("Expected (λ * t)", round(expected_n, 2), theme = "secondary", showcase = icon("calculator")),
        value_box("Empirical Mean Inter-arrival", ifelse(is.na(mean_ia), "N/A", paste0(mean_ia, "s")), theme = "info", showcase = icon("clock")),
        value_box("Theoretical Expected Time (1/λ)", paste0(round(1/rate_per_sec, 3), "s"), theme = "secondary", showcase = icon("book"))
      )
    })
    
    output$stepPlot <- renderPlot({
      times <- sim_times()
      # Construct step function data boundaries (include origin 0 and absolute endpoint)
      df <- data.frame(
        time = c(0, times, input$duration),
        count = c(0, seq_along(times), length(times))
      )
      
      ggplot(df, aes(x = time, y = count)) +
        geom_step(color = "#2C3E50", linewidth = 1.2) +
        geom_point(data = df[-c(1, nrow(df)), ], aes(x = time, y = count), color = "#E74C3C", size = 2) +
        theme_minimal(base_size = 15) +
        labs(
          x = "Time (seconds)", 
          y = "Number of Events N(t)",
          subtitle = paste("Realized path of a Poisson Process with λ =", input$rate, "per", names(which(c("1"="Second", "60"="Minute", "3600"="Hour") == input$timeUnit)))
        ) +
        scale_x_continuous(expand = c(0, 0), limits = c(0, input$duration)) +
        theme(
          plot.subtitle = element_text(color = "grey40", face = "italic"),
          panel.grid.minor = element_blank()
        )
    })
  })
}

shinyApp(ui, server)
